// 流式事件 —— 统一事件模型，前端按 type 分支处理
type ChatEvent struct {
	Type string `protobuf:"bytes,1,opt,name=type" json:"type,omitempty"` // session / retrieval / delta / reasoning / citation / done / error

	// type=session
	SessionId int64 `protobuf:"varint,2,opt,name=session_id" json:"session_id,omitempty"`
	MsgId     int64 `protobuf:"varint,3,opt,name=msg_id" json:"msg_id,omitempty"`

	// type=delta / reasoning
	Delta string `protobuf:"bytes,4,opt,name=delta" json:"delta,omitempty"`

	// type=citation
	Citation *Citation `protobuf:"bytes,5,opt,name=citation" json:"citation,omitempty"`

	// type=retrieval（检索阶段完成，可先展示引用来源）
	HitCount   int32 `protobuf:"varint,6,opt,name=hit_count" json:"hit_count,omitempty"`
	RetrieveMs int64 `protobuf:"varint,7,opt,name=retrieve_ms" json:"retrieve_ms,omitempty"`

	// type=done
	Message     *ChatMessage          `protobuf:"bytes,8,opt,name=message" json:"message,omitempty"`
	Usage       *Usage                `protobuf:"bytes,9,opt,name=usage" json:"usage,omitempty"`
	Degradation *commonv1.Degradation `protobuf:"bytes,10,opt,name=degradation" json:"degradation,omitempty"`

	// type=error
	ErrorCode    string `protobuf:"bytes,11,opt,name=error_code" json:"error_code,omitempty"`
	ErrorMessage string `protobuf:"bytes,12,opt,name=error_message" json:"error_message,omitempty"`
	LlmMs        int64  `protobuf:"varint,13,opt,name=llm_ms" json:"llm_ms,omitempty"`
}

